import numpy as np

qasm_string = """OPENQASM 3.0;
include "stdgates.inc";
include "oracle.inc";

qubit[10] q;
bit[10] c;

// Create superposition over all 32 states
// (The Oracle will likely just ignore or return 0 for states 27-31)
h q[0];
h q[1];
h q[2];
h q[3];
h q[4];

// Apply Oracle
Oracle q[0], q[1], q[2], q[3], q[4], q[5], q[6], q[7], q[8], q[9];

// Measure all qubits
measure q[0] -> c[0];
measure q[1] -> c[1];
measure q[2] -> c[2];
measure q[3] -> c[3];
measure q[4] -> c[4];
measure q[5] -> c[5];
measure q[6] -> c[6];
measure q[7] -> c[7];
measure q[8] -> c[8];
measure q[9] -> c[9];
"""

from qiskit import transpile

def run_and_analyze(circuit, aer_sim):
    # Run the circuit with enough shots to see all 27 inputs
    # The probability of seeing all 27 inputs in 1024 shots is extremely high
    result = aer_sim.run(circuit, shots=2048).result()
    counts = result.get_counts()

    # We want to group inputs by their output
    groups = {}
    for bitstring in counts:
        # Qiskit returns bitstrings as c[9]...c[0]
        # c[9..5] is output, c[4..0] is input
        out_bits = bitstring[:5]
        in_bits = bitstring[5:]

        x_val = int(in_bits, 2)
        if x_val >= 27:
            continue # ignore invalid inputs if any

        if out_bits not in groups:
            groups[out_bits] = set()
        groups[out_bits].add(x_val)

    # Find a group with at least 2 elements
    for out_bits, xs in groups.items():
        xs_list = list(xs)
        if len(xs_list) >= 2:
            x1, x2 = xs_list[0], xs_list[1]

            # calculate difference in trits
            def int_to_trits(v):
                # v = t2*9 + t1*3 + t0
                # Returns [t2, t1, t0]
                return [(v // 9) % 3, (v // 3) % 3, v % 3]

            t1 = int_to_trits(x1)
            t2 = int_to_trits(x2)

            diff1 = [(a - b) % 3 for a, b in zip(t1, t2)]
            diff2 = [(b - a) % 3 for a, b in zip(t1, t2)]

            # return the normalized one (first non-zero is 1)
            # or just return diff1. Let's return the one where the first non-zero is 1.
            d = diff1
            for val in d:
                if val != 0:
                    if val == 2:
                        d = diff2
                    break

            s1 = "".join(map(str, d))
            return s1

    return "000"
